window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-deeb74498e9080e7"]={"versions": [{"id": "FIG-deeb74498e9080e7", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitdiagramm / Timing-Diagramm zur Veranschaulichung des AUTOSAR Virtual Function Bus (VFB) Timing-Modells, speziell des <code>PeriodicEventModel</code>. Es visualisiert die zeitlichen Parameter Periode (<code>Period (modeled)</code>) und Jitter (<code>Jitter (modeled)</code>) bezogen auf eine periodische Ereignisabfolge.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse (Baseline)</strong>: Horizontale Referenzlinie für den zeitlichen Ablauf.</li>\n<li><strong>Periodische Referenzzeitpunkte</strong>: Vertikale gestrichelte Hilfslinien im äquidistanten Abstand der modellierten Periode (<code>Period (modeled)</code>).</li>\n<li><strong>Ereignis-Auftreten (Event Occurrences)</strong>: Nach unten gerichtete Pfeile, die das tatsächliche Eintreffen von Ereignissen markieren.</li>\n<li><strong>Verzögerungsbalken (Delay)</strong>: Horizontale rote Linienabschnitte, die die zeitliche Abweichung der tatsächlichen Ereignisse vom jeweiligen idealen Periodenzeitpunkt darstellen.</li>\n<li><strong>Minimale / Maximale Verzögerung (<code>Min. delay</code>, <code>Max. delay</code>)</strong>: Kennzeichnung des minimalen und maximalen beobachteten Verzögerungswerts innerhalb der Sequenz.</li>\n<li><strong>Modellierter Jitter (<code>Jitter (modeled)</code>)</strong>: Blauer horizontaler Referenzbalken am unteren Diagrammbereich, der die zulässige Differenz zwischen maximaler und minimaler Verzögerung definiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ideale periodische Referenzzeitpunkte treten mit fester Taktzeit (<code>Period (modeled)</code>) auf.</li>\n<li>Reale Ereignisse treten mit individuellen zeitlichen Verzögerungen gegenüber der idealen Taktflanke auf.</li>\n<li>Aus der Gesamtheit der Ereignisse wird das Ereignis mit der geringsten Verzögerung (<code>Min. delay</code>) und das mit der größten Verzögerung (<code>Max. delay</code>) identifiziert.</li>\n<li>Die Differenz zwischen maximaler und minimaler Verzögerung (<code>Max. delay - Min. delay</code>) wird nach unten projiziert und dem modellierten Jitter (<code>Jitter (modeled)</code>) gegenübergestellt.</li>\n<li>Da die gemessene Spreizung (<code>Max. delay - Min. delay</code>) kleiner oder gleich dem modellierten Jitter ist, erfüllt die Ereignisabfolge die Bedingungen des <code>PeriodicEventModel</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Kriterium für die Konformität einer Ereigniskette mit dem AUTOSAR <code>PeriodicEventModel</code>: Eine Folge von Ereignissen genügt dem periodischen Modell mit gegebener Periode und Jitter genau dann, wenn die Differenz aus maximaler und minimaler Verzögerung bezüglich der periodischen Baseline den spezifizierten Jitter nicht überschreitet. Entwickler und Timing-Analysten müssen beachten, dass Jitter hier als Variationsbreite (Peak-to-Peak Delay Difference) bezogen auf die periodische Basis modelliert wird und nicht als absolute Phasenverschiebung.</p>"}, {"id": "FIG-cae6d973d3c23e64", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Zeitdiagramm / Timing-Diagramm zur Veranschaulichung des AUTOSAR Virtual Function Bus (VFB) Timing-Modells, speziell des <code>PeriodicEventModel</code>. Es visualisiert die zeitlichen Parameter Periode (<code>Period (modeled)</code>) und Jitter (<code>Jitter (modeled)</code>) bezogen auf eine periodische Ereignisabfolge.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zeitachse (Baseline)</strong>: Horizontale Referenzlinie für den zeitlichen Ablauf.</li>\n<li><strong>Periodische Referenzzeitpunkte</strong>: Vertikale gestrichelte Hilfslinien im äquidistanten Abstand der modellierten Periode (<code>Period (modeled)</code>).</li>\n<li><strong>Ereignis-Auftreten (Event Occurrences)</strong>: Nach unten gerichtete Pfeile, die das tatsächliche Eintreffen von Ereignissen markieren.</li>\n<li><strong>Verzögerungsbalken (Delay)</strong>: Horizontale rote Linienabschnitte, die die zeitliche Abweichung der tatsächlichen Ereignisse vom jeweiligen idealen Periodenzeitpunkt darstellen.</li>\n<li><strong>Minimale / Maximale Verzögerung (<code>Min. delay</code>, <code>Max. delay</code>)</strong>: Kennzeichnung des minimalen und maximalen beobachteten Verzögerungswerts innerhalb der Sequenz.</li>\n<li><strong>Modellierter Jitter (<code>Jitter (modeled)</code>)</strong>: Blauer horizontaler Referenzbalken am unteren Diagrammbereich, der die zulässige Differenz zwischen maximaler und minimaler Verzögerung definiert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ideale periodische Referenzzeitpunkte treten mit fester Taktzeit (<code>Period (modeled)</code>) auf.</li>\n<li>Reale Ereignisse treten mit individuellen zeitlichen Verzögerungen gegenüber der idealen Taktflanke auf.</li>\n<li>Aus der Gesamtheit der Ereignisse wird das Ereignis mit der geringsten Verzögerung (<code>Min. delay</code>) und das mit der größten Verzögerung (<code>Max. delay</code>) identifiziert.</li>\n<li>Die Differenz zwischen maximaler und minimaler Verzögerung (<code>Max. delay - Min. delay</code>) wird nach unten projiziert und dem modellierten Jitter (<code>Jitter (modeled)</code>) gegenübergestellt.</li>\n<li>Da die gemessene Spreizung (<code>Max. delay - Min. delay</code>) kleiner oder gleich dem modellierten Jitter ist, erfüllt die Ereignisabfolge die Bedingungen des <code>PeriodicEventModel</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Kriterium für die Konformität einer Ereigniskette mit dem AUTOSAR <code>PeriodicEventModel</code>: Eine Folge von Ereignissen genügt dem periodischen Modell mit gegebener Periode und Jitter genau dann, wenn die Differenz aus maximaler und minimaler Verzögerung bezüglich der periodischen Baseline den spezifizierten Jitter nicht überschreitet. Entwickler und Timing-Analysten müssen beachten, dass Jitter hier als Variationsbreite (Peak-to-Peak Delay Difference) bezogen auf die periodische Basis modelliert wird und nicht als absolute Phasenverschiebung.</p>"}], "trans": [{"from": "FIG-deeb74498e9080e7", "to": "FIG-cae6d973d3c23e64", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
